# Generated by build.py from recipe.yml for recipe http-download-to-a-chosen-folder. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'site/docs', 'site/reports/2026' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/docs/guide.txt'), "the guide`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/reports/2026/summary.txt'), "the summary`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --create-dirs --output-dir downloads -o handbook.txt http://127.0.0.1:8080/docs/guide.txt -O http://127.0.0.1:8080/reports/2026/summary.txt -w "%{filename_effective}\n" } finally { Stop-Process $server0 }
